from itertools import permutations

# Generate all possible permutations of columns for 26 queens
solutions = list(permutations(range(26)))

# Check each permutation to see if it's a valid solution
for solution in solutions:
    valid = True
    for i in range(26):
        for j in range(i+1, 26):
            if solution[i] == solution[j] or abs(solution[i] - solution[j]) == abs(i - j):
                valid = False
                break
        if not valid:
            break
    if valid:
        print(solution)
        break
